`SELECT rowid AS source_rowid,project_id,${id} AS resource_id,session_id,created_at,
    '${input?'tool-input':'event'}' AS resource_kind FROM ${table} INDEXED BY ${input?'idx_tool_calls_session':'idx_events_session'}
    WHERE (project_id,session_id,created_at,rowid)>(?,?,?,?) ORDER BY project_id,session_id,created_at,rowid LIMIT ?`

`SELECT project_id, parse_error, parse_failed_at, CASE WHEN json_type(parser_context, '$.mycoParserFailure') = 'object' THEN json_extract(parser_context, '$.mycoParserFailure') END AS diagnostic FROM transcripts INDEXED BY idx_transcripts_backlog
                WHERE parsed_offset < size AND parse_error IS NOT NULL AND parse_error <> '${AWAITING_BYTES}' AND NOT (${RETRY_STOPPED}) AND parser_version >= ? AND NOT ${TOMBSTONED}
                  AND EXISTS (SELECT 1 FROM projects p WHERE p.project_id = transcripts.project_id AND p.archived_at IS NULL)`

`INSERT OR IGNORE INTO processed_resources (${processedColumns.join(', ')})
      SELECT ${processedColumns.map(() => '?').join(', ')} WHERE ${outcomeMatch.sql} AND ${inputMatch.sql}
        AND (NOT EXISTS (SELECT 1 FROM tool_calls WHERE project_id = ? AND tool_call_id = ?) OR ${toolMatch.sql})`

`INSERT INTO restore_reference_guard (missing)
    SELECT 'tool input closure' WHERE ${outcomeMatch.sql} AND ${inputMatch.sql} AND ${toolMatch.sql}
      AND NOT (${[processedMatch.sql, ...proofChecks.map(check => check.sql)].join(' AND ')})`

`SELECT CASE WHEN EXISTS (
      SELECT 1 FROM agent_runs WHERE project_id = ? AND id = ?${guard.sql}
    ) THEN 1 ELSE json_extract('[]', ?) END AS admitted`

